const fs = require('fs');
const path = require('path');

const dir = __dirname;
const manifestPath = path.join(dir, 'backup-manifest.json');

const entries = fs.readdirSync(dir, { withFileTypes: true });
const files = entries
  .filter((e) => e.isFile())
  .filter((e) => !e.name.startsWith('.'))
  .filter((e) => e.name !== 'backup-manifest.json')
  .filter((e) => e.name !== 'backup.js')
  .map((e) => e.name)
  .sort();

fs.writeFileSync(manifestPath, JSON.stringify({ files }, null, 2) + '\n');
console.log(JSON.stringify({ files }, null, 2));

